alter table public.supplier_listings add column branch_id uuid references public.supplier_branches(id),add column warehouse_id uuid references public.supplier_warehouses(id);
alter table public.supplier_quotes add column branch_id uuid references public.supplier_branches(id);
alter table public.orders add column fulfilment_branch_id uuid references public.supplier_branches(id),add column fulfilment_warehouse_id uuid references public.supplier_warehouses(id);
create index idx_listings_location on public.supplier_listings(supplier_id,branch_id,warehouse_id);create index idx_orders_fulfilment_location on public.orders(supplier_id,fulfilment_branch_id,fulfilment_warehouse_id);
create or replace function public.member_has_branch_access(target_org uuid,target_branch uuid)returns boolean language sql stable security definer set search_path=public as $$select target_branch is null or exists(select 1 from organisation_members m where m.organisation_id=target_org and m.user_id=auth.uid()and m.status='active'and m.is_active and(not exists(select 1 from branch_memberships x where x.membership_id=m.id)or exists(select 1 from branch_memberships x where x.membership_id=m.id and x.branch_id=target_branch)))$$;
create or replace function public.member_has_warehouse_access(target_org uuid,target_warehouse uuid)returns boolean language sql stable security definer set search_path=public as $$select target_warehouse is null or exists(select 1 from organisation_members m where m.organisation_id=target_org and m.user_id=auth.uid()and m.status='active'and m.is_active and(not exists(select 1 from warehouse_memberships x where x.membership_id=m.id)or exists(select 1 from warehouse_memberships x where x.membership_id=m.id and x.warehouse_id=target_warehouse)))$$;
create or replace function public.member_has_project_access(target_org uuid,target_project uuid)returns boolean language sql stable security definer set search_path=public as $$select target_project is null or exists(select 1 from organisation_members m where m.organisation_id=target_org and m.user_id=auth.uid()and m.status='active'and m.is_active and(not exists(select 1 from project_memberships x where x.membership_id=m.id)or exists(select 1 from project_memberships x where x.membership_id=m.id and x.project_id=target_project)))$$;
drop policy if exists "supplier listing member read"on public.supplier_listings;create policy "supplier listing assignment read"on public.supplier_listings for select using((has_permission('products.view',supplier_id)and member_has_branch_access(supplier_id,branch_id)and member_has_warehouse_access(supplier_id,warehouse_id))or is_platform_admin());
drop policy if exists "supplier listing member insert"on public.supplier_listings;create policy "supplier listing assignment insert"on public.supplier_listings for insert with check(has_permission('products.create',supplier_id)and member_has_branch_access(supplier_id,branch_id)and member_has_warehouse_access(supplier_id,warehouse_id)and exists(select 1 from organisations where id=supplier_id and verification_status='approved'));
drop policy if exists "supplier listing member update"on public.supplier_listings;create policy "supplier listing assignment update"on public.supplier_listings for update using((has_permission('products.edit',supplier_id)and member_has_branch_access(supplier_id,branch_id)and member_has_warehouse_access(supplier_id,warehouse_id))or is_platform_admin())with check((has_permission('products.edit',supplier_id)and member_has_branch_access(supplier_id,branch_id)and member_has_warehouse_access(supplier_id,warehouse_id))or is_platform_admin());
drop policy if exists "supplier listing member delete"on public.supplier_listings;create policy "supplier listing assignment delete"on public.supplier_listings for delete using((has_permission('products.edit',supplier_id)and member_has_branch_access(supplier_id,branch_id)and member_has_warehouse_access(supplier_id,warehouse_id))or is_platform_admin());
drop policy if exists "order supplier read"on public.orders;create policy "order supplier assignment read"on public.orders for select using(has_permission('orders.view',supplier_id)and member_has_branch_access(supplier_id,fulfilment_branch_id)and member_has_warehouse_access(supplier_id,fulfilment_warehouse_id));
create or replace function public.customer_can_read_order(target public.orders)returns boolean language sql stable security definer set search_path=public as $$select target.customer_id=auth.uid()or(target.customer_organisation_id is not null and has_permission('organisation.view',target.customer_organisation_id)and member_has_project_access(target.customer_organisation_id,target.project_id))$$;
create or replace function public.customer_can_read_quote_request(target public.quote_requests)returns boolean language sql stable security definer set search_path=public as $$select target.requester_id=auth.uid()or(target.organisation_id is not null and has_permission('quotations.view',target.organisation_id)and member_has_project_access(target.organisation_id,target.project_id))$$;
drop policy if exists "organisation purchase request read"on public.purchase_requests;create policy "organisation assigned purchase request read"on public.purchase_requests for select using(has_permission('organisation.view',organisation_id)and member_has_project_access(organisation_id,project_id));
drop policy if exists "project owner access"on public.projects;drop policy if exists "project organisation member read"on public.projects;create policy "project assigned organisation read"on public.projects for select using((organisation_id is null and owner_id=auth.uid())or(organisation_id is not null and has_permission('organisation.view',organisation_id)and member_has_project_access(organisation_id,id))or is_platform_admin());create policy "project scoped insert"on public.projects for insert with check((organisation_id is null and owner_id=auth.uid())or(organisation_id is not null and owner_id=auth.uid()and has_permission('projects.create',organisation_id)));create policy "project scoped update"on public.projects for update using((organisation_id is null and owner_id=auth.uid())or(organisation_id is not null and has_permission('projects.edit',organisation_id)and member_has_project_access(organisation_id,id)))with check((organisation_id is null and owner_id=auth.uid())or(organisation_id is not null and has_permission('projects.edit',organisation_id)and member_has_project_access(organisation_id,id)));create policy "project scoped delete"on public.projects for delete using((organisation_id is null and owner_id=auth.uid())or(organisation_id is not null and has_permission('organisation.manage',organisation_id)));
revoke all on function public.member_has_branch_access(uuid,uuid),public.member_has_warehouse_access(uuid,uuid),public.member_has_project_access(uuid,uuid)from public,anon;grant execute on function public.member_has_branch_access(uuid,uuid),public.member_has_warehouse_access(uuid,uuid),public.member_has_project_access(uuid,uuid)to authenticated;
